from rendu import Point

p = Point(4)
p.h('Les menaces immédiates passent avant la fréquence habituelle')
p.p('Devant une déformation traumatique du poignet, l’examen de la peau, des nerfs et de la vascularisation détermine d’abord la priorité.', 'p82-radius')
p.p('La branche 🚩 E1 est ouverte si la fracture menace ces structures ; une fracture ouverte impose notamment l’appel de la garde de chirurgie de la main.', 'p82-radius')
p.p('Les HUG associent alors le bilan vasculo-nerveux, les radiographies, le réalignement et la prévention antibiotique dans la prise en charge spécialisée.', 'p82-radius')
p.p('La branche 🚩 E2 est envisagée devant un pied diabétique rouge, chaud et gonflé, car un Charcot actif peut précéder la déformation durable.', 'p82-charcot')
p.p('L’immobilisation et la décharge commencent dès que ce diagnostic est considéré ; elles ne sont pas reportées jusqu’à une déformation radiographique évidente.', 'p82-charcot')
p.p('Une douleur nocturne persistante ou une douleur fébrile chez l’enfant impose aussi des investigations sans délai, plutôt qu’une conclusion de variante normale.', 'p82-plat-examen')
p.fenetre('Deux pièges qui peuvent retarder la protection', [
    ('Une radiographie normale n’exclut pas un Charcot actif si le tableau clinique persiste ; l’imagerie par résonance magnétique complète alors le bilan.', 'p82-charcot'),
    ('Si cette imagerie avancée est inaccessible, la recommandation prévoit une prise en charge comme Charcot actif probable, au lieu d’abandonner la protection.', 'p82-charcot'),
    ('Une déformation majeure après fracture peut s’accompagner d’une menace cutanée ou vasculo-nerveuse ; le réalignement est alors discuté dans la filière urgente.', 'p82-radius'),
    ('L’examen neurologique du poignet recherche notamment les territoires radial, ulnaire et médian, ce qui évite de résumer la main à son aspect osseux.', 'p82-radius'),
])
p.h('Dix diagnostics canoniques, organisés par contexte de fréquence')
p.p('L’arthrose de la main, l’hallux valgus et les variantes pédiatriques occupent les premiers contextes fréquents décrits par les sources suisses.', ['p82-arthrose', 'p82-hallux', 'p82-plat-physio', 'p82-genou'])
p.p('Le traumatisme, la neuropathie et la croissance disproportionnée définissent ensuite des cadres distincts, dans lesquels changent les hypothèses et les priorités.', ['p82-radius', 'p82-charcot', 'p82-xlh-clinique'])
p.h('DX.1 — Arthrose déformante de la main')
p.p('Ce premier contexte concerne une atteinte articulaire fréquente avec l’âge ; la douleur à l’usage et la déformation orientent l’examen localisé.', 'p82-arthrose')
p.h('DX.2 — Hallux valgus')
p.p('Dans l’avant-pied, cette déformation fréquente associe déviation du gros orteil et du métatarsien, avec un retentissement souvent lié au chaussage.', 'p82-hallux')
p.h('DX.3 — Pied plat valgus souple physiologique de l’enfant')
p.p('Pendant la croissance, le caractère flexible et indolore permet de reconnaître une variante développementale fréquente plutôt qu’une maladie imposant un traitement.', ['p82-plat-physio', 'p82-plat-examen'])
p.h('DX.4 — Désaxation physiologique du genou de l’enfant')
p.p('Les variations frontales du genou sont un autre motif fréquent de consultation pédiatrique, avec une histoire naturelle distincte des déformations rachitiques.', ['p82-genou', 'p82-xlh-clinique'])
p.h('DX.5 — Doigt en maillet')
p.p('Le CHUV décrit comme très fréquent ce défaut d’extension terminale, dont la lésion tendineuse se distingue d’une rétraction aponévrotique.', ['p82-maillet', 'p82-dupuytren'])
p.h('DX.6 — Maladie de Dupuytren')
p.p('Chez l’adulte, la présence de cordes palmaires et d’une rétraction progressive définit un autre mécanisme de limitation digitale.', 'p82-dupuytren')
p.h('DX.7 — Scoliose idiopathique de l’adolescent')
p.p('Dans le territoire rachidien, cette forme prédomine parmi les scolioses et demande une appréciation de la courbure et de la croissance.', 'p82-scoliose-definition')
p.h('DX.8 — Fracture déplacée de l’extrémité distale du radius')
p.p('Après traumatisme, le déplacement du radius devient une hypothèse précise ; la fragilité chez le sujet âgé et la haute énergie orientent le contexte.', 'p82-radius')
p.h('DX.9 — Neuro-ostéoarthropathie de Charcot du pied diabétique')
p.p('Le terrain neuropathique et l’inflammation du pied définissent ce cadre particulier, où la protection précoce vise à prévenir la déformation progressive.', 'p82-charcot')
p.h('DX.10 — Rachitisme hypophosphatémique lié à l’X avec déformation des membres inférieurs')
p.p('Cette cause rare devient pertinente devant une progression des déformations et une croissance disproportionnée, avec recherche de pertes rénales de phosphate.', ['p82-xlh-definition', 'p82-xlh-clinique', 'p82-xlh-mecanisme-bilan'])
p.tableau(['Signe clé', 'Examen qui tranche', 'Mécanisme', 'Conduite immédiate', 'Rang E'], [
    [('Dans l’arthrose déformante de la main, la douleur mécanique accompagne les articulations gonflées ou déformées.', 'p82-arthrose'), ('L’examen localise l’atteinte ; une imagerie ciblée se choisit ensuite selon la présentation articulaire.', 'p82-arthrose-diagnostic'), ('L’atteinte cartilagineuse et les changements articulaires produisent le tableau dégénératif décrit.', 'p82-arthrose'), ('La prise en charge commence par des moyens adaptés au retentissement, notamment physiothérapie et attelles.', 'p82-arthrose-diagnostic'), ('Le tableau mécanique habituel ne porte pas de badge E dans cette organisation.', 'p82-arthrose-diagnostic')],
    [('Dans l’hallux valgus, la saillie médiale peut frotter dans la chaussure tandis que le gros orteil dévie.', 'p82-hallux'), ('L’examen identifie le premier rayon et précise la douleur, le chaussage et les déformations associées.', 'p82-hallux'), ('Les directions opposées du gros orteil et du métatarsien expliquent l’angle visible.', 'p82-hallux'), ('La gêne au chaussage et le retentissement sont appréciés avant de déterminer la prise en charge.', 'p82-hallux'), ('La déformation isolée ne reçoit pas de badge E ; le tableau peut être asymptomatique.', 'p82-hallux')],
    [('Dans le pied plat valgus souple physiologique de l’enfant, l’arche s’efface en charge mais reste réductible.', 'p82-plat-examen'), ('La position sur la pointe des pieds et l’extension du gros orteil permettent d’observer la reformation de la voûte.', 'p82-plat-examen'), ('L’architecture du pied évolue pendant la croissance, ce qui explique cette variante fréquente.', 'p82-plat-physio'), ('Un pied flexible indolore et sans instabilité de marche conduit à rassurer les parents puis à observer.', 'p82-plat-examen'), ('Le tableau typique ne reçoit pas de badge E ; une douleur fébrile change immédiatement de branche.', 'p82-plat-examen')],
    [('Dans la désaxation physiologique du genou de l’enfant, le varus ou le valgus s’interprète selon la croissance.', 'p82-genou'), ('L’axe est apprécié couché puis debout, avec une position reproductible et les rotules orientées de face.', 'p82-genou-examen'), ('Le morphotype frontal varie avec le développement, souvent avec une correction spontanée.', 'p82-genou'), ('La surveillance suit l’évolution typique ; une présentation pathologique nécessite une évaluation spécialisée.', 'p82-genou'), ('La variante physiologique ne porte pas de badge E dans ce triage.', 'p82-genou')],
    [('Dans le doigt en maillet, le patient ne parvient plus à tendre activement l’extrémité du doigt.', 'p82-maillet'), ('L’examen distingue la lésion fermée d’une plaie et recherche une composante osseuse avant le choix thérapeutique.', 'p82-maillet'), ('La rupture de l’appareil extenseur terminal explique la perte d’extension distale.', 'p82-maillet'), ('Le doigt est protégé puis évalué pour choisir entre traitement par attelle et prise en charge spécialisée.', 'p82-maillet'), ('Le tableau fermé simple ne porte pas de badge E ; une plaie relève de la branche traumatique adaptée.', 'p82-maillet')],
    [('Dans Dupuytren, des nodules ou cordes palmaires accompagnent une réduction progressive de l’extension.', 'p82-dupuytren'), ('L’examen localise les épaississements de l’aponévrose et le retentissement sur les doigts concernés.', 'p82-dupuytren'), ('La prolifération myofibroblastique épaissit puis rétracte le tissu palmaire sous-cutané.', 'p82-dupuytren'), ('La gêne fonctionnelle et la rétraction orientent une discussion thérapeutique visant l’extension de la main.', 'p82-dupuytren'), ('Cette progression habituelle ne reçoit pas de badge E dans la liste.', 'p82-dupuytren')],
    [('Dans la scoliose idiopathique de l’adolescent, une asymétrie du tronc peut s’accompagner d’une gibbosité.', 'p82-scoliose-clinique'), ('Le test d’Adams précède, selon l’indication, une radiographie complète du rachis debout et la mesure de Cobb.', ['p82-scoliose-clinique', 'p82-scoliose-radio']), ('La déformation est tridimensionnelle, ce qui impose d’examiner aussi la rotation et le plan sagittal.', ['p82-scoliose-definition', 'p82-scoliose-radio']), ('L’examen recherche une cause secondaire et détermine l’orientation selon la croissance et la courbure.', ['p82-scoliose-definition', 'p82-scoliose-irm']), ('Le tableau idiopathique typique ne porte pas de badge E ; des symptômes neurologiques imposent un bilan différent.', 'p82-scoliose-irm')],
    [('Dans la fracture déplacée de l’extrémité distale du radius, le traumatisme précède la déformation douloureuse du poignet.', 'p82-radius'), ('L’examen cutané et vasculo-nerveux est complété par des radiographies de face et de profil.', 'p82-radius'), ('Le déplacement fracturaire modifie la géométrie de l’extrémité distale du radius.', 'p82-radius'), ('Une ouverture ou une menace impose l’appel spécialisé et la prise en charge du réalignement.', 'p82-radius'), ('🚩 E1 s’applique lorsque la peau, la perfusion ou les nerfs sont menacés, notamment en cas de fracture ouverte.', 'p82-radius')],
    [('Dans la neuro-ostéoarthropathie de Charcot du pied diabétique, rougeur, chaleur et gonflement orientent vers une activité inflammatoire.', 'p82-charcot'), ('Les radiographies puis l’imagerie par résonance magnétique évaluent la suspicion, après exclusion des autres causes.', 'p82-charcot'), ('L’inflammation neuropathique peut produire des fractures et luxations progressives responsables de la déformation.', 'p82-charcot'), ('L’immobilisation et la décharge sont engagées dès la suspicion, avec suivi spécialisé rapproché.', 'p82-charcot'), ('🚩 E2 s’applique au Charcot actif suspecté, sans attendre une déformation fixée.', 'p82-charcot')],
    [('Dans le rachitisme hypophosphatémique lié à l’X, les jambes peuvent se déformer progressivement avec une croissance disproportionnée.', 'p82-xlh-clinique'), ('Le phosphate est interprété selon l’âge, puis les pertes rénales et la génétique précisent l’étiologie.', 'p82-xlh-mecanisme-bilan'), ('L’excès de facteur de croissance fibroblastique 23 entraîne une perte rénale de phosphate et une absorption intestinale réduite.', 'p82-xlh-mecanisme-bilan'), ('La déformation progressive ne doit pas être classée physiologique ; une prise en charge métabolique précoce est organisée.', 'p82-xlh-clinique'), ('Cette orientation précoce est distincte des rangs E traumatique et neuropathique.', ['p82-xlh-clinique', 'p82-radius', 'p82-charcot'])],
])
p.h('La présentation atypique réouvre le diagnostic différentiel')
p.p('La douleur, la rigidité ou les signes neurologiques font quitter la branche du pied souple physiologique, même si l’enfant est jeune.', 'p82-plat-examen')
p.p('Une courbure rachidienne atypique ou des symptômes neurologiques conduisent à rechercher une cause secondaire avant de retenir le terme idiopathique.', 'p82-scoliose-irm')
p.p('Une croissance disproportionnée et des anomalies dentaires peuvent renforcer l’hypothèse métabolique, au-delà d’un simple défaut d’alignement des jambes.', 'p82-xlh-clinique')
p.sauver()
